  /**
   * @method
   * @name bybit#cancelOrderWs
   * @description cancels an open order
   * @see https://bybit-exchange.github.io/docs/v5/order/cancel-order
   * @see
   * https://bybit-exchange.github.io/docs/v5/websocket/trade/guideline#createamendcancel-order
   * @param {string} id order id
   * @param {string} symbol unified symbol of the market the order was made in
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {boolean} [params.trigger] *spot only* whether the order is a
   * trigger order
   * @param {string} [params.orderFilter] *spot only* 'Order' or 'StopOrder' or
   * 'tpslOrder'
   * @returns {object} An [order structure]{@link
   * https://docs.ccxt.com/?id=order-structure}
   */
  std::shared_future<ccxt::any>
  cancelOrderWs(ccxt::any id, ccxt::any symbol = ccxt::any{},
                ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 if (isTrue(isEqual(symbol, ccxt::any{}))) {
                   throw ArgumentsRequired(toString(add(
                       this->id,
                       std::string(
                           " cancelOrderWs() requires a symbol argument"))));
                 }
                 ccxt::any orderRequest =
                     this->cancelOrderRequest(id, symbol, params);
                 ccxt::any url = ::getValue(
                     ::getValue(
                         ::getValue(::getValue(this->urls, std::string("api")),
                                    std::string("ws")),
                         std::string("private")),
                     std::string("trade"));
                 awaitValue(this->authenticate(url));
                 ccxt::any requestId = toString(this->requestId());
                 if (isTrue(inOp(orderRequest, std::string("orderFilter")))) {
                   deleteKey(orderRequest, std::string("orderFilter"));
                 }
                 ccxt::any request = ccxt::dict{
                     {std::string("op"), std::string("order.cancel")},
                     {std::string("reqId"), requestId},
                     {std::string("args"), ccxt::list{orderRequest}},
                     {std::string("header"),
                      ccxt::dict{
                          {std::string("X-BAPI-TIMESTAMP"),
                           toString(this->milliseconds())},
                          {std::string("X-BAPI-RECV-WINDOW"),
                           toString(::getValue(this->options,
                                               std::string("recvWindow")))},
                      }},
                 };
                 return awaitValue(
                     this->watch(url, requestId, request, requestId, true));
               })
        .share();
  }

  /**
   * @method
   * @name bybit#watchTicker
   * @description watches a price ticker, a statistical calculation with the
   * information calculated over the past 24 hours for a specific market
   * @see https://bybit-exchange.github.io/docs/v5/websocket/public/ticker
   * @see https://bybit-exchange.github.io/docs/v5/websocket/public/etp-ticker
   * @param {string} symbol unified symbol of the market to fetch the ticker for
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} a [ticker structure]{@link
   * https://docs.ccxt.com/?id=ticker-structure}
   */
  std::shared_future<ccxt::any>
  watchTicker(ccxt::any symbol, ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 ccxt::any market = this->market(symbol);
                 symbol = ::getValue(market, std::string("symbol"));
                 ccxt::any messageHash = add(std::string("ticker:"), symbol);
                 ccxt::any url = awaitValue(this->getUrlByMarketType(
                     symbol, false, std::string("watchTicker"), params));
                 params = this->cleanParams(params);
                 ccxt::any options = this->safeValue(
                     this->options, std::string("watchTicker"), ccxt::dict{});
                 ccxt::any topic = this->safeString(options, std::string("name"),
                                                   std::string("tickers"));
                 if (isTrue(
                         isTrue((!isEqual(
                             ::getValue(market, std::string("spot")), true))) &&
                         isTrue(!isEqual(topic, std::string("tickers"))))) {
                   throw BadRequest(toString(
                       add(this->id,
                           std::string(" watchTicker() only supports name "
                                       "tickers for contract markets"))));
                 }
                 topic = add(topic, add(std::string("."),
                                        ::getValue(market, std::string("id"))));
                 ccxt::any topics = ccxt::list{topic};
                 return awaitValue(this->watchTopics(
                     url, ccxt::list{messageHash}, topics, params));
               })
        .share();
  }

  /**
   * @method
   * @name bybit#watchTickers
   * @description watches a price ticker, a statistical calculation with the
   * information calculated over the past 24 hours for all markets of a specific
   * list
   * @see https://bybit-exchange.github.io/docs/v5/websocket/public/ticker
   * @see https://bybit-exchange.github.io/docs/v5/websocket/public/etp-ticker
   * @param {string[]} symbols unified symbol of the market to fetch the ticker
   * for
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} a [ticker structure]{@link
   * https://docs.ccxt.com/?id=ticker-structure}
   */
  std::shared_future<ccxt::any>
  watchTickers(ccxt::any symbols = ccxt::any{},
               ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 symbols = this->marketSymbols(symbols, ccxt::any{}, false);
                 ccxt::any messageHashes = ccxt::list{};
                 ccxt::any url = awaitValue(this->getUrlByMarketType(
                     ::getValue(symbols, 0), false, std::string("watchTickers"),
                     params));
                 params = this->cleanParams(params);
                 ccxt::any options = this->safeValue(
                     this->options, std::string("watchTickers"), ccxt::dict{});
                 ccxt::any topic = this->safeString(options, std::string("name"),
                                                   std::string("tickers"));
                 ccxt::any marketIds = this->marketIds(symbols);
                 ccxt::any topics = ccxt::list{};
                 for (ccxt::any i = 0; isLessThan(i, getArrayLength(marketIds));
                      postFixIncrement(i)) {
                   ccxt::any marketId = ::getValue(marketIds, i);
                   arrayPush(topics,
                             add(add(topic, std::string(".")), marketId));
                   arrayPush(messageHashes, add(std::string("ticker:"),
                                                ::getValue(symbols, i)));
                 }
                 ccxt::any ticker = awaitValue(
                     this->watchTopics(url, messageHashes, topics, params));
                 if (isTrue(this->newUpdates)) {
                   ccxt::any result = ccxt::dict{};
                   ::setValue(result, ::getValue(ticker, std::string("symbol")),
                              ticker);
                   return result;
                 }
                 return this->filterByArray(this->tickers,
                                            std::string("symbol"), symbols);
               })
        .share();
  }

  /**
   * @method
   * @name bybit#unWatchTickers
   * @description unWatches a price ticker
   * @see https://bybit-exchange.github.io/docs/v5/websocket/public/ticker
   * @see https://bybit-exchange.github.io/docs/v5/websocket/public/etp-ticker
   * @param {string[]} symbols unified symbol of the market to fetch the ticker
   * for
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} a [ticker structure]{@link
   * https://docs.ccxt.com/?id=ticker-structure}
   */
  std::shared_future<ccxt::any>
  unWatchTickers(ccxt::any symbols = ccxt::any{},
                 ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 symbols = this->marketSymbols(symbols, ccxt::any{}, false);
                 ccxt::any options = this->safeValue(
                     this->options, std::string("watchTickers"), ccxt::dict{});
                 ccxt::any topic = this->safeString(options, std::string("name"),
                                                   std::string("tickers"));
                 ccxt::any messageHashes = ccxt::list{};
                 ccxt::any subMessageHashes = ccxt::list{};
                 ccxt::any marketIds = this->marketIds(symbols);
                 ccxt::any topics = ccxt::list{};
                 for (ccxt::any i = 0; isLessThan(i, getArrayLength(marketIds));
                      postFixIncrement(i)) {
                   ccxt::any marketId = ::getValue(marketIds, i);
                   ccxt::any symbol = ::getValue(symbols, i);
                   arrayPush(topics,
                             add(add(topic, std::string(".")), marketId));
                   arrayPush(subMessageHashes,
                             add(std::string("ticker:"), symbol));
                   arrayPush(messageHashes,
                             add(std::string("unsubscribe:ticker:"), symbol));
                 }
                 ccxt::any url = awaitValue(this->getUrlByMarketType(
                     ::getValue(symbols, 0), false, std::string("watchTickers"),
                     params));
                 return awaitValue(this->unWatchTopics(
                     url, std::string("ticker"), symbols, messageHashes,
                     subMessageHashes, topics, params));
               })
        .share();
  }

